import React, { createContext, useContext, useEffect, useMemo, useState, useCallback } from 'react';
import { NativeModules, Platform, View } from 'react-native';
import * as SecureStore from 'expo-secure-store';

// Lightweight i18n for the native OWNER app. A flat key -> string map per
// language, a t() with {var} interpolation, and a language setter persisted in
// expo-secure-store under a key DISTINCT from the consumer app's. Offline-first,
// no network. en is the source of truth; every t('…') call site resolves against
// en first if the active language lacks a key, and finally against the raw key,
// so nothing on the UI ever renders blank or as a key name.
//
// en + hi are fully authored. bn/gu/mr are authored HERE (batch LANG): every key
// whose concept already exists in mobile-app/src/consumer/i18n.js reuses that
// exact consumer string so the two flavors speak with one voice, and the rest is
// written in the same plain shopkeeper register. They have NOT yet been read by a
// native speaker — docs/i18n-review-bn-gu-mr.md is the review sheet and the source
// of truth for corrections, and they keep the "(beta)" marker in the picker until
// that review lands. All ten are fully selectable in Settings.
//
// ta/te/kn/ml/ur began as a verbatim transcription of the owner-facing strings a
// human had already translated in the web dashboard (admin-dashboard/src/lib/i18n.js)
// — 123 of en's keys — and fell back to English for everything else, which left
// those five shopkeepers reading an English app for order editing, the new-order
// alert, shop hours, ready-times, families and settings. Batch DRAVIDIAN-URDU
// AUTHORED the remaining 197 keys in each, following the vocabulary of that
// language's own transcribed block so one word means one thing throughout. Those
// 197 per language are MACHINE-AUTHORED and have been read by nobody who speaks
// the language: docs/i18n-review-owner-app.md lists every one of them, money and
// order strings first, and is the source of truth for corrections.
//
// A key is deliberately ABSENT where the English fallback already renders exactly
// right — a brand name ('txn.upi' is "UPI" in every source that has it, and
// 'app.name' / 'app.shortName' / 'title.dashboard' are all "Smart Khata"),
// "Razorpay Key ID", and a format string that is nothing but placeholders and
// punctuation ('oedit.historyReduced', 'oedit.historyBy'). Absent beats a row that
// changes nothing on screen. "HH:MM" is no longer one of them: hi spells the field
// hint out as घंटा:मिनट, and every other language now does the same in its script.
//
// Real coverage per language is NOT 100% and is not claimed to be. The repo-root
// scripts/i18n-coverage.mjs measures it against en and fails CI on a regression.

// Persist key — deliberately separate from the consumer app's 'skhata_consumer_lang'
// so the two flavors keep independent language choices on the same device.
const LANG_KEY = 'skhata_owner_lang';

// Supported languages, in picker order, with native labels (same set/order/labels
// as the consumer app).
export const LANGUAGES = [
  { code: 'en', label: 'English' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'bn', label: 'বাংলা' },
  { code: 'ta', label: 'தமிழ்' },
  { code: 'te', label: 'తెలుగు' },
  { code: 'kn', label: 'ಕನ್ನಡ' },
  { code: 'ml', label: 'മലയാളം' },
  { code: 'mr', label: 'मराठी' },
  { code: 'gu', label: 'ગુજરાતી' },
  { code: 'ur', label: 'اردو' },
];

// Languages the picker marks "(beta)". bn/gu/mr now have a translated owner
// catalogue (batch LANG) but it has NOT been read by a native speaker yet, so the
// marker stays until docs/i18n-review-bn-gu-mr.md comes back checked — it is the
// honest signal, not a coverage claim. They stay fully selectable either way.
// Honest, offline, no capability fetch.
export const BETA_LANGS = new Set(['bn', 'gu', 'mr']);
export function isBetaLang(code) {
  return BETA_LANGS.has(code);
}

